package com.hospital.dao;
import com.hospital.model.Patient;import com.hospital.util.DBConnection;
import java.sql.*;import java.util.*;
public class PatientDAO {
 public long create(String name,java.sql.Date dob,String gender,String phone,String address,String blood)throws SQLException{String q="INSERT INTO patients(full_name,date_of_birth,gender,phone,address,blood_group) VALUES(?,?,?,?,?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setDate(2,dob);p.setString(3,gender);p.setString(4,phone);p.setString(5,address);p.setString(6,blood);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();return r.getLong(1);}}}
 public List<Patient> search(String term,int limit,int offset,Long doctor)throws SQLException{String q="SELECT * FROM patients WHERE active=1 AND (full_name LIKE ? OR phone LIKE ? OR CAST(patient_id AS CHAR)=?) AND (? IS NULL OR EXISTS(SELECT 1 FROM appointments a WHERE a.patient_id=patients.patient_id AND a.doctor_id=?)) ORDER BY full_name LIMIT ? OFFSET ?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){String t="%"+term+"%";p.setString(1,t);p.setString(2,t);p.setString(3,term);if(doctor==null){p.setNull(4,Types.BIGINT);p.setNull(5,Types.BIGINT);}else{p.setLong(4,doctor);p.setLong(5,doctor);}p.setInt(6,limit);p.setInt(7,offset);try(ResultSet r=p.executeQuery()){List<Patient> out=new ArrayList<>();while(r.next())out.add(map(r));return out;}}}
 public Patient find(long id,Long doctor)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM patients WHERE patient_id=? AND (? IS NULL OR EXISTS(SELECT 1 FROM appointments a WHERE a.patient_id=patients.patient_id AND a.doctor_id=?))")){p.setLong(1,id);if(doctor==null){p.setNull(2,Types.BIGINT);p.setNull(3,Types.BIGINT);}else{p.setLong(2,doctor);p.setLong(3,doctor);}try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}}
 public void update(long id,String name,java.sql.Date dob,String gender,String phone,String address,String blood)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE patients SET full_name=?,date_of_birth=?,gender=?,phone=?,address=?,blood_group=? WHERE patient_id=? AND active=1")){p.setString(1,name);p.setDate(2,dob);p.setString(3,gender);p.setString(4,phone);p.setString(5,address);p.setString(6,blood);p.setLong(7,id);if(p.executeUpdate()==0)throw new SQLException("Active patient not found.");}}
 public void deactivate(long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE patients SET active=0 WHERE patient_id=? AND active=1")){p.setLong(1,id);if(p.executeUpdate()==0)throw new SQLException("Active patient not found.");}}
 private Patient map(ResultSet r)throws SQLException{return new Patient(r.getLong("patient_id"),r.getString("full_name"),r.getDate("date_of_birth").toLocalDate(),r.getString("gender"),r.getString("phone"),r.getString("address"),r.getString("blood_group"),r.getTimestamp("registered_at").toLocalDateTime(),r.getBoolean("active"));}
}
